package com.mohymods.kingdomsmp.economy;
import static org.junit.jupiter.api.Assertions.*;
import com.mohymods.kingdomsmp.persistence.AtomicNbt;
import com.mohymods.kingdomsmp.profession.*;
import java.nio.file.Path;
import java.io.IOException;
import java.util.*;
import net.minecraft.nbt.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
/** Canonical replay models, not evidence of native rarity or acquisition. */
class LibrarySpellCatalogueStoreTest {
 @TempDir Path directory;
 static List<LibrarySpellCatalogue.Fact> facts(){return List.of(new LibrarySpellCatalogue.Fact("irons_spellbooks:acupuncture",1,"RARE"),new LibrarySpellCatalogue.Fact("irons_spellbooks:blood_needles",4,"RARE"),new LibrarySpellCatalogue.Fact("irons_spellbooks:blood_slash",1,"RARE"),new LibrarySpellCatalogue.Fact("irons_spellbooks:blood_step",2,"RARE"));}
 static CompoundTag item(LibrarySpellCatalogue.Fact f){var item=new CompoundTag();item.putString("id","irons_spellbooks:scroll");item.putInt("count",1);var components=new CompoundTag();var c=new CompoundTag();var data=new ListTag();var spell=new CompoundTag();spell.putString("id",f.spell());spell.putInt("level",f.level());spell.putInt("index",0);spell.putBoolean("locked",true);data.add(spell);c.put("data",data);c.putInt("maxSpells",1);c.putBoolean("mustEquip",false);c.putBoolean("spellWheel",false);components.put("irons_spellbooks:spell_container",c);item.put("components",components);return item;}
 @Test void differentSpellIdsNotIdenticalItemIdsPinNativeFactsAndRecoverOnceAlongsideOldGlyphHistory()throws Exception{
  var f=new LibraryJourneymanStoreTest();f.directory=directory;var s=f.earnedApprentice();var admin=UUID.randomUUID();var g=s.prepareLibraryCatalogue(UUID.randomUUID(),f.p,admin,LibraryGlyphCatalogueStoreTest.items(),"Pure canonical earlier glyph inspection boundary");s.recoverItem(new EconomyStore.Receipt(s.id(),g.sequence()));var facts=facts();var items=facts.stream().map(LibrarySpellCatalogueStoreTest::item).toList();var payload=facts.stream().map(LibrarySpellCatalogue.Fact::save).toList();var pending=s.prepareLibraryCatalogue(UUID.randomUUID(),f.p,admin,LibrarySpellCatalogue.QUEST,items,payload,"Pure canonical native spell inspection boundary");assertEquals(1000,s.professions(f.p).track(Profession.LIBRARIAN).xp());assertFalse(s.recoverItem(new EconomyStore.Receipt(s.id(),s.expectedReceipt(f.p))));pending=s.prepareLibraryCatalogue(UUID.randomUUID(),f.p,admin,LibrarySpellCatalogue.QUEST,items,payload,"Pure canonical inspected spell delivery");long sequence=pending.sequence();var fault=EconomyStore.open(directory,(file,data)->{AtomicNbt.write(file,data);throw new IOException("Native spell catalogue after-rename uncertainty");});assertThrows(IOException.class,()->fault.recoverItem(new EconomyStore.Receipt(s.id(),sequence)));var restored=EconomyStore.open(directory);assertFalse(restored.recoverItem(new EconomyStore.Receipt(s.id(),sequence)));assertEquals(1200,restored.professions(f.p).track(Profession.LIBRARIAN).xp());assertTrue(restored.professions(f.p).track(Profession.LIBRARIAN).completedQuestIds().containsAll(Set.of(LibraryGlyphCatalogue.QUEST,LibrarySpellCatalogue.QUEST)));assertThrows(IllegalStateException.class,()->restored.prepareLibraryCatalogue(UUID.randomUUID(),f.p,admin,LibrarySpellCatalogue.QUEST,items,payload,"Repeat native spell catalogue"));restored.archive(admin,"Native spell and legacy glyph catalogue model");assertEquals(restored.professions(f.p),EconomyStore.open(directory).professions(f.p));
 }
 @Test void wrongNativeSpellLevelDuplicateSpellFakeRarityAndMissingFactsRefuse(){
  var facts=facts();var input=facts.stream().map(LibrarySpellCatalogueStoreTest::item).toList();var proof=facts.stream().map(LibrarySpellCatalogue.Fact::save).toList();LibrarySpellCatalogue.validate(input,proof);assertThrows(IllegalArgumentException.class,()->LibrarySpellCatalogue.validate(input,List.of()));var duplicate=new ArrayList<>(input);duplicate.set(3,input.getFirst());var copied=new ArrayList<>(proof);copied.set(3,proof.getFirst());assertThrows(IllegalArgumentException.class,()->LibrarySpellCatalogue.validate(duplicate,copied));var altered=new ArrayList<>(input);altered.set(0,item(new LibrarySpellCatalogue.Fact(facts.getFirst().spell(),2,"RARE")));assertThrows(IllegalArgumentException.class,()->LibrarySpellCatalogue.validate(altered,proof));var fake=new ArrayList<>(proof);fake.set(0,proof.getFirst().copy());fake.getFirst().putString("rarity","COMMON");assertThrows(IllegalArgumentException.class,()->LibrarySpellCatalogue.validate(input,fake));
 }
}
